import Icons from './utils/Icons.js';
import Swiper from 'swiper/bundle';

class Main {
  constructor() {
    this.init();
  }

  init() {
    Icons.load();

    this.initSwiperPaginationEvenement();
    this.initSwiperPaginationConferencier();
  }

  initSwiperPaginationEvenement() {
    const swiper = new Swiper('.swiper-event', {
      loop: true,

      pagination: {
        el: '.swiper-pagination-event',
      },
    });
  }

  initSwiperPaginationConferencier() {
    const swiper = new Swiper('.swiper-conferenciers', {
      loop: true,

      pagination: {
        el: '.swiper-pagination-conferencier',
      },
      slidesPerView: 3,
      spaceBetween: 30,
      breakpoints: {
        default: {
          slidesPerView: 1,
        },
        480: {
          slidesPerView: 1,
        },
        768: {
          slidesPerView: 2,
        },
        1024: {
          slidesPerView: 3,
        },
      },
    });
  }
}
new Main();

const boutonModale = document.querySelector('.js-toggle');

const modale = document.querySelector('.modale');

boutonModale.addEventListener('click', openModale);

function openModale() {
  console.log('sup');
  modale.classList.add('visible');
  modale.addEventListener('click', closeModale);
}

function closeModale() {
  modale.classList.remove('visible');
}
